style.css:
@-moz-document domain("youtube.com") {
/* Set background to the Blueprint image */
body {
  background: url("https://i.imgur.com/4JcYkuV.jpg") no-repeat center center fixed !important;
  background-size: cover !important;
  margin: 0;
  padding: 0;
  overflow: hidden;
}

/* Soft blue overlay for text readability */
body::before {
  content: "";
  position: fixed;
  top: 0;
  left: 0;
  width: 100vw;
  height: 100vh;
  background: rgba(0, 15, 40, 0.3);
  z-index: 0;
}

/* Overlay text */
body::after {
  content: "B L U E P R I N T \A\A STRAY KIDS \A\A BANG CHAN / LEEKNOW / CHANGBIN / HYUNJIN / HAN / FELIX / SEUNGMIN / I.N";
  white-space: pre;
  font-family: 'Georgia', serif;
  font-size: 1.4em;
  color: white;
  text-align: center;
  position: fixed;
  top: 22%;
  left: 50%;
  transform: translateX(-50%);
  z-index: 1;
  text-shadow: 0 2px 5px rgba(0, 0, 0, 0.7);
  line-height: 2.5em;
  letter-spacing: 3px;
}
}
